  "supportive_card_ids": ["C01", "C10", "C16", "C17", "C20", "C24", "C37", "C40", "C53", "C66", "C80"],
  "contradictory_card_ids": ["C35"],
  "prediction_basis_card_ids": ["C01", "C16", "C17", "C40"],
  "claims": [
    {
      "claim": "The query is moclobemide and no direct absolute bioavailability measurement for it appears in the supplied records, but the close structural analog sematilide, a para-substituted benzamide with a basic amine, has human absolute oral bioavailability of 47 to 59% across multiple studies.",
      "card_ids": ["C01", "C10", "C20", "C24", "C37"]
    },
    {
      "claim": "Morpholine-containing small-molecule reference drugs have measured human F values well above 20%, including molsidomine 44 to 59% and linezolid about 93 to 100%, which supports F at or above 20% for this morpholine amide.",
      "card_ids": ["C16", "C17", "C40", "C19", "C18"]
    },
    {
      "claim": "L4 fraction-absorbed records for small-molecule analogs show high absorption, including levocetirizine at least 85%, NAPA 87 to 92%, isoniazid 97 to 99%, and bepotastine above 85%, indicating absorption is not the limiting step.",
      "card_ids": ["C53", "C54", "C55", "C56", "C57", "C59", "C61", "C64"]
    },
    {
      "claim": "L5 bidirectional permeability records for morpholine-containing and related analogs show high apical-to-basolateral permeability with efflux ratios near unity or below, including SUVN-G3031 0.81, compound 20 0.5, and compound 5v 1.0, so gut-wall efflux is unlikely to reduce F below the threshold.",
      "card_ids": ["C66", "C67", "C72", "C74", "C75"]
    },
    {
      "claim": "L6 hepatic clearance and metabolic stability records are for other molecules and are mixed, with stable examples such as SUVN-G3031 in human hepatocytes and compound 10b in rat microsomes, and higher clearance examples such as compound 22 and compound 2a; none measure moclobemide, so they provide no affirmative low-F hepatic evidence.",
      "card_ids": ["C77", "C78", "C79", "C80", "C81", "C82", "C83", "C84", "C85", "C86", "C87", "C88"]
    },
    {
      "claim": "The only sub-20% measured F among supplied references is linezolid in mice at 18.4%, which is species-specific and contradicted by human linezolid F of about 93 to 100%, so it does not provide transferable low-F evidence for the query.",
      "card_ids": ["C35", "C40", "C19", "C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C77", "C78", "C79", "C80", "C81", "C82", "C83", "C84", "C85", "C86", "C87", "C88"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for moclobemide itself in the supplied records.",
    "No direct hepatic clearance or metabolic stability measurement for moclobemide; all L6 records concern other molecules.",
    "No modified-release formulation-specific bioavailability data for the query or a close analog; modified release may alter absorption kinetics but no evidence indicates F below 20%.",
    "First-pass metabolism extent for the query is not directly quantified.",
    "Several supporting records are from non-human species and are used only as context."
  ],
  "decision_summary": "Predicted high with F at or above 20% and moderate confidence. The close analog sematilide has human F of 47 to 59%, morpholine and amide references have F of 44 to 100%, and L3 oral exposure, L4 high fraction absorbed, and L5 low-efflux high-permeability records all support absorption. L6 hepatic records are for other molecules with mixed results and do not provide affirmative low-F evidence. The only sub-20% value, linezolid in mice at 18.4%, is species-specific and not transferable. The modified-release formulation adds uncertainty but no affirmative evidence for F below 20%."
}

